  const clock=new THREE.Clock();
  // Flight controls use inertia and the ship's own frame; the drag gesture banks the nose.
  const turnSpeed=1.25;
  if(keys.has('ArrowLeft'))yaw+=turnSpeed*dt;if(keys.has('ArrowRight'))yaw-=turnSpeed*dt;
  if(keys.has('ArrowUp'))pitch=Math.min(1.25,pitch+turnSpeed*dt);if(keys.has('ArrowDown'))pitch=Math.max(-1.25,pitch-turnSpeed*dt);
  if(keys.has('KeyQ'))roll+=turnSpeed*dt;if(keys.has('KeyE')&&!el('buildModal').classList.contains('open'))roll-=turnSpeed*dt;
  ship.rotation.set(pitch,yaw+Math.PI,roll,'YXZ');
  const forward=new THREE.Vector3(0,0,-1).applyQuaternion(ship.quaternion),right=new THREE.Vector3(1,0,0).applyQuaternion(ship.quaternion),up=new THREE.Vector3(0,1,0).applyQuaternion(ship.quaternion);
  const input=new THREE.Vector3();if(keys.has('KeyW'))input.add(forward);if(keys.has('KeyS'))input.sub(forward);if(keys.has('KeyD'))input.add(right);if(keys.has('KeyA'))input.sub(right);if(keys.has('Space')||keys.has('KeyR'))input.add(up);if(keys.has('KeyC'))input.sub(up);
  const boost=keys.has('ShiftLeft')||keys.has('ShiftRight');const maxSpeed=boost?72:42;const accel=(boost?38:22)*ship.userData.thrust;
  if(input.lengthSq()>0){input.normalize();shipVelocity.addScaledVector(input,accel*dt);}
  shipVelocity.multiplyScalar(Math.exp(-.32*dt));if(shipVelocity.length()>maxSpeed)shipVelocity.setLength(maxSpeed);
  ship.position.addScaledVector(shipVelocity,dt);
  // Keep the playable neighborhood around the forge; the belt still feels expansive due to parallax.
  if(ship.position.length()>590){ship.position.setLength(590);shipVelocity.multiplyScalar(.35);toast('SECTOR LIMIT // NAVIGATION BOUNDARY');}
  const camOffset=new THREE.Vector3(0,7.6,22).applyQuaternion(ship.quaternion);const cameraGoal=ship.position.clone().add(camOffset);
  camera.position.lerp(cameraGoal,1-Math.exp(-4.2*dt));const lookPoint=ship.position.clone().addScaledVector(forward,13).add(new THREE.Vector3(0,1,0));camera.lookAt(lookPoint);
  // Light mining salvage eases toward the player and is automatically recovered on approach.
  for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.rotation.x+=dt*.8;p.rotation.y+=dt*1.1;p.userData.phase+=dt;const dist=p.position.distanceTo(ship.position);if(dist<36)p.position.lerp(ship.position,1-Math.exp(-(dist<13?5:1.6)*dt));if(dist<4){ore+=p.userData.amount;scene.remove(p);pickups.splice(i,1);updateHUD();if(ore>=30&&forgeSystems===0)el('objective').innerHTML='<b>OBJECTIVE //</b> Return to the orbital forge and fabricate a system';}}
  // Asteroids and fragments drift very slowly, keeping the scene alive without losing targets.
  for(const a of asteroids){a.rotation.x+=dt*.012;a.rotation.y+=dt*.009;}
  energy=Math.min(ship.userData.capacity,energy+(ship.position.distanceTo(forge.position)<42?16:2.4)*dt);
  const forgeDist=ship.position.distanceTo(forge.position);el('forgeDistance').textContent=`${Math.round(forgeDist)} M`;el('speedText').textContent=String(Math.round(shipVelocity.length())).padStart(2,'0');el('energyBar').style.width=`${Math.max(0,energy/ship.userData.capacity*100)}%`;el('energyText').textContent=`${Math.round(energy/ship.userData.capacity*100)}%`;
  if(forgeDist<34){el('shipStatus').textContent='DOCKING RANGE';el('shipStatus').style.color='var(--amber)';}else{el('shipStatus').textContent='ONLINE';el('shipStatus').style.color='var(--cyan)';}
  // Identify the object under the central engineering reticle.
  raycaster.setFromCamera(center,camera);const visibleHits=raycaster.intersectObjects(asteroids,false);if(visibleHits.length&&visibleHits[0].distance<190){const hit=visibleHits[0];el('targetLabel').textContent=`ORE ASTEROID // ${Math.round(hit.distance)} M`;el('reticle').classList.add('active');}else{el('targetLabel').textContent='';el('reticle').classList.remove('active');}
  if(performance.now()-lastToast>1900)el('toast').classList.remove('show');
  renderer.render(scene,camera);
}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));});
updateHUD();animate();
</script>
</body>
</html>

