const modules=[{id:'thrusters',icon:'↗',name:'Ion Thrusters',desc:'Twin vector engines. Push deeper into the belt with greater acceleration.',cost:35,effect:'THRUST +40%',apply(){ship.userData.thrust=1.4;}},{id:'capacitor',icon:'ϟ',name:'Flux Capacitor',desc:'A high-density cell keeps the mining laser charged for longer sorties.',cost:30,effect:'ENERGY +50%',apply(){ship.userData.capacity=150;energy=150;}},{id:'drill',icon:'✧',name:'Resonance Drill',desc:'Focused pulse frequency extracts more alloy from every asteroid.',cost:40,effect:'YIELD +50%',apply(){ship.userData.yield=1.5;}}];
