function makePickup(pos,amount){const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.8),new THREE.MeshStandardMaterial({color:0x7affdc,emissive:0x19bca6,emissiveIntensity:2,metalness:.5}));gem.position.copy(pos);gem.userData={amount};scene.add(gem);pickups.push(gem);}
function updateHUD(){el('oreCount').textContent=String(ore).padStart(3,'0');el('energyBar').style.width=`${energy/ship.userData.capacity*100}%`;el('energyText').textContent=`${Math.round(energy/ship.userData.capacity*100)}%`;el('hullBar').style.width=`${hullHealth}%`;el('hullText').textContent=`${hullHealth}%`;el('progressCount').textContent=`${forgeSystems} / 3`;el('missionProgress').style.width=`${forgeSystems/3*100}%`;if(forgeSystems>=3){el('missionTitle').textContent='Forge Online';el('missionText').textContent='Three systems are live. Your ship is ready for the frontier.';el('objective').innerHTML='<b>CONTRACT COMPLETE //</b> Forge systems online — the frontier is yours';}else if(ore>=30){el('objective').innerHTML='<b>OBJECTIVE //</b> Return to the orbital forge and fabricate a system';}else if(forgeSystems){el('objective').innerHTML=`<b>OBJECTIVE //</b> Fabricate ${3-forgeSystems} more ship system${forgeSystems===2?'':'s'} at the orbital forge`;}}
function refreshBuild(){const grid=el('buildGrid');grid.innerHTML='';for(const m of modules){const owned=!!ship.userData[m.id],card=document.createElement('div');card.className='build-card';card.innerHTML=`<div class="build-icon">${m.icon}</div><h3>${m.name}</h3><p>${m.desc}</p><div class="cost">${owned?'INSTALLED':`COST // ${m.cost} ALLOY · ${m.effect}`}</div><button class="build-button" ${owned||ore<m.cost?'disabled':''}>${owned?'✓ INSTALLED':ore<m.cost?'NEED MORE ALLOY':'FABRICATE SYSTEM'}</button>`;card.querySelector('button').addEventListener('click',()=>{if(owned||ore<m.cost)return;ore-=m.cost;ship.userData[m.id]=true;m.apply();forgeSystems++;toast(`${m.name.toUpperCase()} FABRICATED`);updateHUD();refreshBuild();});grid.appendChild(card);}}
function openBuild(){if(ship.position.distanceTo(forge.position)>120){toast('OUT OF RANGE // APPROACH THE ORBITAL FORGE');return;}el('buildModal').classList.add('open');refreshBuild();}
function shootLine(){const start=ship.position.clone().add(new THREE.Vector3(0,0,-5).applyQuaternion(ship.quaternion)),end=start.clone().add(new THREE.Vector3(0,0,-1).applyQuaternion(ship.quaternion).multiplyScalar(45)),line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([start,end]),new THREE.LineBasicMaterial({color:0x62f5df,transparent:true,opacity:.9}));scene.add(line);setTimeout(()=>{scene.remove(line);line.geometry.dispose();line.material.dispose();},90);}
function mine(){if(!gameStarted||el('buildModal').classList.contains('open'))return;if(energy<3){toast('ENERGY LOW // RETURN TO FORGE');return;}raycaster.setFromCamera(center,camera);const hits=raycaster.intersectObjects(asteroids,false);if(!hits.length||hits[0].distance>185)return;const rock=hits[0].object;energy=Math.max(0,energy-2.8);shootLine();rock.material.emissive.set(0x236b60);rock.material.emissiveIntensity=.9;setTimeout(()=>{if(rock.material){rock.material.emissive.set(0);rock.material.emissiveIntensity=0;}},100);rock.userData.hp=(rock.userData.hp??3)-1;if(rock.userData.hp<=0){const count=Math.max(2,Math.ceil(rock.userData.ore*ship.userData.yield/8));for(let i=0;i<count;i++)makePickup(rock.position.clone().add(new THREE.Vector3(THREE.MathUtils.randFloatSpread(7),THREE.MathUtils.randFloatSpread(7),THREE.MathUtils.randFloatSpread(7))),Math.ceil(rock.userData.ore*ship.userData.yield/count));scene.remove(rock);asteroids.splice(asteroids.indexOf(rock),1);toast('ASTEROID FRACTURED // SALVAGE RELEASED');setTimeout(()=>{const a=Math.random()*Math.PI*2,r=THREE.MathUtils.randFloat(90,260);makeAsteroid(Math.cos(a)*r,Math.sin(a)*r*.6,THREE.MathUtils.randFloat(-270,90),THREE.MathUtils.randFloat(.75,1.2));},4000);}updateHUD();}
function launch(){gameStarted=true;el('startScreen').classList.add('hide');toast('FLIGHT SYSTEMS ONLINE');}el('launch').addEventListener('click',launch);el('closeBuild').addEventListener('click',()=>el('buildModal').classList.remove('open'));
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='KeyE'||e.code==='KeyB'){if(el('buildModal').classList.contains('open'))el('buildModal').classList.remove('open');else openBuild();}if(e.code==='Escape')el('buildModal').classList.remove('open');if(e.code==='Enter'&&!gameStarted)launch();if(e.code==='Space'&&gameStarted)mine();});window.addEventListener('keyup',e=>keys.delete(e.code));
